// Kenen luut? A real photo of a skull or a skeleton, and four animals to
// choose from (photos of the living animals, name below, said aloud on tap).
// Every photo is CC / public domain from Wikimedia Commons: lib/data.ts
// (generated by tools/luut/build.py) keeps author, licence and source, shown
// under each photo and on the "Kuvat" screen.
//
// Difficulty: a round has ten questions. Wrong answers are first picked from
// other kinds of animals (a bird vs a cat), later one or two come from the
// same kind (a cat vs a dog). Look-alikes (cat / lion / tiger, dog / wolf /
// fox ...) are never offered together, so every question can be solved by
// looking.

import { ANIMALS, CREDITS, CONFUSE } from "lib/data";

type Mode = "menu" | "play" | "done" | "credits";
type Pic = { f: string; k: string; c: string };
type Animal = { id: string; name: string; g: string; alive: string; emoji: string; ac: string; pics: Pic[] };
type Q = { a: number; pic: Pic; opts: number[] };

const ROUND = 10;
const LEVELS = [
  { name: rg.t("Kallot", "Skulls", "Cráneos"), sub: rg.t("Kenen pääkallo?", "Whose skull?", "¿De quién es el cráneo?"), icon: "💀", color: "#7b5e3b", kinds: ["kallo"] },
  { name: rg.t("Luurangot", "Skeletons", "Esqueletos"), sub: rg.t("Kenen luuranko?", "Whose skeleton?", "¿De quién es el esqueleto?"), icon: "🦴", color: "#457b9d", kinds: ["luuranko"] },
  { name: rg.t("Sekaisin", "Mixed", "Mezclados"), sub: rg.t("Kalloja ja luurankoja", "Skulls and skeletons", "Cráneos y esqueletos"), icon: "🔍", color: "#2a9d8f", kinds: ["kallo", "luuranko"] },
];
const PRAISE = ["hyva", "hienoa", "mahtavaa", "oikein", "loistavaa", "jee", "taitava", "osaat"];
const PER_PAGE = 6;

let mode: Mode = "menu";
let level = 0;
let task = 0;
let right = 0;
let t = 0;
let q: Q = { a: 0, pic: { f: "", k: "kallo", c: "" }, opts: [] };
let wrong: number[] = [];   // options already tried this question
let solved = -1;
let shake = { i: -1, t: 0 };
let best: number[] = [0, 0, 0];
let recent: number[] = [];
let page = 0;
let praiseN = 0;

const A: Animal[] = ANIMALS as any;
// the animals' names in English and Spanish (the clips say them by the Finnish id)
const NAMES: any = {
  "Delfiini": ["Dolphin", "Delfín"],
  "Dinosaurus": ["Dinosaur", "Dinosaurio"],
  "Gorilla": ["Gorilla", "Gorila"],
  "Hai": ["Shark", "Tiburón"],
  "Hevonen": ["Horse", "Caballo"],
  "Hirvi": ["Moose", "Alce"],
  "Hylje": ["Seal", "Foca"],
  "Ihminen": ["Human", "Humano"],
  "Kala": ["Fish", "Pez"],
  "Kameli": ["Camel", "Camello"],
  "Kana": ["Hen", "Gallina"],
  "Kani": ["Rabbit", "Conejo"],
  "Karhu": ["Bear", "Oso"],
  "Kenguru": ["Kangaroo", "Canguro"],
  "Kettu": ["Fox", "Zorro"],
  "Kilpikonna": ["Turtle", "Tortuga"],
  "Kirahvi": ["Giraffe", "Jirafa"],
  "Kissa": ["Cat", "Gato"],
  "Koira": ["Dog", "Perro"],
  "Krokotiili": ["Crocodile", "Cocodrilo"],
  "Käärme": ["Snake", "Serpiente"],
  "Lammas": ["Sheep", "Oveja"],
  "Lehmä": ["Cow", "Vaca"],
  "Leijona": ["Lion", "León"],
  "Lepakko": ["Bat", "Murciélago"],
  "Majava": ["Beaver", "Castor"],
  "Mursu": ["Walrus", "Morsa"],
  "Norsu": ["Elephant", "Elefante"],
  "Orava": ["Squirrel", "Ardilla"],
  "Peura": ["Deer", "Ciervo"],
  "Pingviini": ["Penguin", "Pingüino"],
  "Pöllö": ["Owl", "Búho"],
  "Rotta": ["Rat", "Rata"],
  "Sammakko": ["Frog", "Rana"],
  "Sarvikuono": ["Rhino", "Rinoceronte"],
  "Seepra": ["Zebra", "Cebra"],
  "Siili": ["Hedgehog", "Erizo"],
  "Sika": ["Pig", "Cerdo"],
  "Simpanssi": ["Chimpanzee", "Chimpancé"],
  "Strutsi": ["Ostrich", "Avestruz"],
  "Susi": ["Wolf", "Lobo"],
  "Tiikeri": ["Tiger", "Tigre"],
  "Valas": ["Whale", "Ballena"],
  "Virtahepo": ["Hippo", "Hipopótamo"]
};
function nm(i: number) { const n = NAMES[A[i].name]; return n ? rg.t(A[i].name, n[0], n[1]) : A[i].name; }

function init() {
  best = rg.load("best", [0, 0, 0]);
  while (best.length < LEVELS.length) best.push(0);
}

function confusable(a: number, b: number): boolean {
  const x = A[a].id, y = A[b].id;
  for (const set of CONFUSE as string[][]) if (set.indexOf(x) >= 0 && set.indexOf(y) >= 0) return true;
  return false;
}

function hasKind(i: number, kinds: string[]) { return A[i].pics.some((p) => kinds.indexOf(p.k) >= 0); }

// how many wrong answers come from the same kind of animal: 0 at the start
// of a round, 1 in the middle, 2 at the end
function nearCount() { return task < 3 ? 0 : task < 7 ? 1 : 2; }

function makeQuestion() {
  const kinds = LEVELS[level].kinds;
  const all: number[] = [];
  for (let i = 0; i < A.length; i++) if (hasKind(i, kinds)) all.push(i);
  let pool = all.filter((i) => recent.indexOf(i) < 0);
  if (pool.length === 0) { recent = []; pool = all; }
  const a = rg.pick(pool);
  recent.push(a);
  while (recent.length > Math.max(1, Math.floor(all.length * 0.7))) recent.shift();
  const pics = A[a].pics.filter((p) => kinds.indexOf(p.k) >= 0);
  const pic = rg.pick(pics);
  const opts = [a];
  const ok = (i: number) => opts.indexOf(i) < 0 && !opts.some((o) => confusable(o, i));
  const near = rg.shuffle(A.map((_, i) => i).filter((i) => A[i].g === A[a].g));
  const far = rg.shuffle(A.map((_, i) => i).filter((i) => A[i].g !== A[a].g));
  let n = nearCount();
  for (const i of near) { if (n <= 0) break; if (ok(i)) { opts.push(i); n--; } }
  for (const i of far) { if (opts.length >= 4) break; if (ok(i) && !opts.some((o) => o !== a && A[o].g === A[i].g)) opts.push(i); }
  for (const i of far) { if (opts.length >= 4) break; if (ok(i)) opts.push(i); }
  q = { a, pic, opts: rg.shuffle(opts) };
}

function ask() { rg.say(q.pic.k === "kallo" ? "kenen_kallo" : "kenen_luuranko"); }
function sayName(i: number) { rg.say(rg.sayId.word(A[i].name)); }

function next() {
  wrong = [];
  solved = -1;
  shake = { i: -1, t: 0 };
  makeQuestion();
  ask();
}

function choose(j: number) {
  if (solved >= 0) return;
  const i = q.opts[j];
  if (wrong.indexOf(i) >= 0) { sayName(i); return; }
  if (i === q.a) {
    solved = t;
    if (wrong.length === 0) right++;
    const col = j % 2, row = Math.floor(j / 2);
    rg.celebrate(width / 2 + (col === 0 ? -80 : 80), height - 260 + row * 140, { sound: false });
    rg.sound(wrong.length === 0 ? "star" : "coin");
    praiseN++;
    rg.say([rg.sayId.word(A[i].name), PRAISE[praiseN % PRAISE.length]]);
  } else {
    wrong.push(i);
    shake = { i: j, t };
    rg.sound("wrong");
    rg.vibrate(60);
    rg.say([rg.sayId.word(A[i].name), "kokeile_toista"]);
  }
}

function startLevel(i: number) {
  level = i;
  task = 0;
  right = 0;
  mode = "play";
  rg.sound("click");
  rg.music("calm", { volume: 0.3 });
  next();
}

function tick(dt: number) {
  t += dt;
  if (mode === "play" && solved >= 0 && t - solved > 2.2) {
    task++;
    if (task >= ROUND) {
      mode = "done";
      rg.stopMusic();
      if (right > best[level]) { best[level] = right; rg.save("best", best); }
      if (right >= 5) rg.celebrate(width / 2, height * 0.3, { big: true }); else rg.sound("coin");
      rg.say(right >= 2 ? [right >= 8 ? "mahtavaa" : right >= 5 ? "hienoa" : "hyvin_meni", "sait", rg.sayId.number(right), "tahtea"] : ["hyvin_meni"]);
    } else next();
  }
}

function toMenu() { mode = "menu"; rg.stopMusic(); rg.stopSay(); rg.sound("click"); }
function onBack() { if (mode === "menu") rg.exit(); else toMenu(); }

// ---- drawing -----------------------------------------------------------------

function wobble(j: number) {
  if (shake.i !== j) return 0;
  const k = Math.max(0, 1 - (t - shake.t) / 0.4);
  return Math.sin((t - shake.t) * 50) * 9 * k;
}

function Progress() {
  const dots = [];
  for (let i = 0; i < ROUND; i++) dots.push(<div className={i < task ? "dotdone" : i === task ? "dotnow" : "dot"} />);
  return <div className="progress">{dots}</div>;
}

function Play() {
  // the photo takes what the four choices leave over
  const ph = Math.max(150, Math.min(240, height - 470));
  const pw = Math.round(ph * 4 / 3);
  const done = solved >= 0;
  return (
    <div className="screen">
      {Progress()}
      <div className="ask" id="ask" onClick={() => ask()}>🔊 {q.pic.k === "kallo" ? rg.t("Kenen pääkallo?", "Whose skull?", "¿De quién es el cráneo?") : rg.t("Kenen luuranko?", "Whose skeleton?", "¿De quién es el esqueleto?")}</div>
      <div className="photo" style={{ width: pw + 12, height: ph + 12 }} onClick={() => ask()}>
        <img className="photoimg" src={rg.asset(q.pic.f)} style={{ width: pw, height: ph }} />
      </div>
      <div className="credit">📷 {q.pic.c}</div>
      <div className="grid">
        {q.opts.map((i, j) => {
          const ok = done && i === q.a;
          const no = wrong.indexOf(i) >= 0;
          const dx = wobble(j);
          return (
            <div className={ok ? "optok" : no ? "optno" : "opt"} id={"o" + j} onClick={() => choose(j)}
              style={{ marginLeft: 6 + dx, marginRight: 6 - dx }}>
              <div className="optpic" style={{ opacity: no ? 0.3 : 1 }}>
                {A[i].alive ? <img className="optimg" src={rg.asset(A[i].alive)} /> : <div className="optemoji">{A[i].emoji}</div>}
              </div>
              <div className="optname">{no ? "✕ " + nm(i) : nm(i)}</div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function Menu() {
  const bob = Math.sin(t * 2.5) * 6;
  return (
    <div className="screen">
      <div className="title" style={{ marginTop: 46 + bob }}>{rg.t("Kenen luut?", "Whose bones?", "¿De quién son los huesos?")}</div>
      <div className="lead">💀 🦴 🦊 🐘 🦉</div>
      {LEVELS.map((L, i) => (
        <div className="level" id={"lv" + i} onClick={() => startLevel(i)} style={{ backgroundColor: L.color }}>
          <div className="lvname">{L.icon} {L.name}</div>
          <div className="lvsub">{L.sub}</div>
          <div className="lvbest">{best[i] > 0 ? "⭐ " + best[i] + "/" + ROUND : ""}</div>
        </div>
      ))}
      <div className="small" id="credits" onClick={() => { mode = "credits"; page = 0; rg.sound("click"); }}><div className="lvname">📷 {rg.t("Kuvat", "Photos", "Fotos")}</div></div>
      <div className="small back" id="exit" onClick={() => rg.exit()}><div className="lvname">{rg.t("← Valikkoon", "← Menu", "← Menú")}</div></div>
    </div>
  );
}

function Credits() {
  const pages = Math.max(1, Math.ceil(CREDITS.length / PER_PAGE));
  const rows = (CREDITS as any[]).slice(page * PER_PAGE, page * PER_PAGE + PER_PAGE);
  return (
    <div className="screen">
      <div className="ctitle">📷 {rg.t("Kuvien tekijät", "Photo credits", "Autores de las fotos")}</div>
      <div className="cnote">{rg.t("Kaikki kuvat Wikimedia Commonsista, vapailla lisensseillä (CC tai vapaa käyttö).", "All photos from Wikimedia Commons under free licences (CC or public domain).", "Todas las fotos son de Wikimedia Commons con licencias libres (CC o dominio público).")}</div>
      {rows.map((c) => (
        <div className="crow">
          <div className="cwhat">{c.what}</div>
          <div className="cwho">{c.author} · {c.license}</div>
          <div className="csrc">{c.file}</div>
        </div>
      ))}
      <div className="pager">
        <div className={page > 0 ? "pbtn" : "pbtnoff"} id="prev" onClick={() => { if (page > 0) { page--; rg.sound("click"); } }}>◀</div>
        <div className="pnum">{page + 1} / {pages}</div>
        <div className={page < pages - 1 ? "pbtn" : "pbtnoff"} id="next" onClick={() => { if (page < pages - 1) { page++; rg.sound("click"); } }}>▶</div>
      </div>
      <div className="small back" id="cback" onClick={() => toMenu()}><div className="lvname">{rg.t("← Takaisin", "← Back", "← Atrás")}</div></div>
    </div>
  );
}

function Done() {
  const stars = [];
  for (let i = 0; i < ROUND; i++) stars.push(<div className={i < right ? "bigstar" : "bigstaroff"}>⭐</div>);
  return (
    <div className="screen">
      <div className="title" style={{ marginTop: 80 }}>{right >= 8 ? rg.t("Mahtavaa!", "Awesome!", "¡Fantástico!") : right >= 5 ? rg.t("Hienoa!", "Great!", "¡Genial!") : rg.t("Hyvä yritys!", "Good try!", "¡Buen intento!")}</div>
      <div className="stars">{stars}</div>
      <div className="lead">{right} / {ROUND} {rg.t("heti oikein", "right first time", "a la primera")}</div>
      <div className="level" id="again" onClick={() => startLevel(level)} style={{ backgroundColor: LEVELS[level].color }}><div className="lvname">{rg.t("Uudestaan!", "Again!", "¡Otra vez!")}</div></div>
      <div className="small back" id="menu" onClick={() => toMenu()}><div className="lvname">{rg.t("← Takaisin", "← Back", "← Atrás")}</div></div>
    </div>
  );
}

function view() {
  let body;
  if (mode === "menu") body = Menu();
  else if (mode === "done") body = Done();
  else if (mode === "credits") body = Credits();
  else body = Play();
  return <div className="root">{body}</div>;
}
